from app import app
from config import AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, S3_BUCKET

def check_aws_credentials():
    if 'default_access_key' in (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, S3_BUCKET):
        print("Warning: Using default AWS credentials. The application may not function correctly.")
        print("Please set the correct AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, and S3_BUCKET environment variables.")
    else:
        print("AWS credentials are set.")

if __name__ == "__main__":
    check_aws_credentials()
    app.run(host="0.0.0.0", port=5000, debug=True)

import os
import logging
from flask import Flask, render_template, request, jsonify, send_file, Response, abort
from werkzeug.utils import secure_filename
from s3_utils import upload_file, download_file, list_files_and_folders, get_file_url, delete_file, create_folder, delete_folder
from config import S3_BUCKET
import mimetypes
import boto3
from botocore.exceptions import ClientError

app = Flask(__name__)
app.config['MAX_CONTENT_LENGTH'] = 1024 * 1024 * 1024 * 1024  # 1 TB

# Set up logging
logging.basicConfig(level=logging.DEBUG)
logger = logging.getLogger(__name__)

CHUNK_SIZE = 100 * 1024 * 1024  # 100 MB chunks

# Update MIME type detection
mimetypes.init()
mimetypes.add_type('image/webp', '.webp')
mimetypes.add_type('image/heic', '.heic')
mimetypes.add_type('image/heif', '.heif')

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/upload', methods=['POST'])
def upload():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400
    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400
    if file:
        filename = secure_filename(file.filename)
        folder = request.form.get('folder', '')
        if folder:
            filename = f"{folder.rstrip('/')}/{filename}"
        try:
            upload_file(file, filename)
            return jsonify({'message': 'File uploaded successfully'}), 200
        except Exception as e:
            logger.error(f"Error uploading file: {str(e)}")
            return jsonify({'error': str(e)}), 500

@app.route('/upload_chunk', methods=['POST'])
def upload_chunk():
    try:
        chunk = request.files['chunk']
        filename = request.form['filename']
        file_size = int(request.form['file_size'])
        chunk_number = int(request.form['chunk_number'])
        total_chunks = int(request.form['total_chunks'])

        logger.info(f"Uploading chunk {chunk_number + 1} of {total_chunks} for file {filename}")

        s3 = boto3.client('s3')
        if file_size < CHUNK_SIZE:
            # Single-part upload for small files
            s3.upload_fileobj(chunk, S3_BUCKET, filename)
            logger.info(f"Single-part upload completed for file {filename}")
            return jsonify({'message': 'File uploaded successfully'}), 200
        else:
            # Multipart upload for larger files
            if chunk_number == 0:
                multipart_upload = s3.create_multipart_upload(Bucket=S3_BUCKET, Key=filename)
                upload_id = multipart_upload['UploadId']
                logger.info(f"Initialized multipart upload for {filename} with UploadId: {upload_id}")
            else:
                upload_id = request.form['upload_id']

            part = s3.upload_part(
                Bucket=S3_BUCKET,
                Key=filename,
                PartNumber=chunk_number + 1,
                UploadId=upload_id,
                Body=chunk
            )

            if chunk_number == total_chunks - 1:
                parts = []
                for i in range(total_chunks):
                    parts.append({
                        'ETag': s3.upload_part(
                            Bucket=S3_BUCKET,
                            Key=filename,
                            PartNumber=i + 1,
                            UploadId=upload_id,
                            Body=''
                        )['ETag'],
                        'PartNumber': i + 1
                    })

                s3.complete_multipart_upload(
                    Bucket=S3_BUCKET,
                    Key=filename,
                    UploadId=upload_id,
                    MultipartUpload={'Parts': parts}
                )
                logger.info(f"Completed multipart upload for {filename}")
                return jsonify({'message': 'File uploaded successfully'}), 200
            else:
                return jsonify({'upload_id': upload_id}), 200

    except Exception as e:
        logger.error(f"Error in upload_chunk: {str(e)}", exc_info=True)
        return jsonify({'error': str(e)}), 500

@app.route('/download/<path:filename>')
def download(filename):
    try:
        s3 = boto3.client('s3')
        file_obj = s3.get_object(Bucket=S3_BUCKET, Key=filename)
        file_size = file_obj['ContentLength']

        def generate():
            offset = 0
            while offset < file_size:
                chunk = min(CHUNK_SIZE, file_size - offset)
                byte_range = f'bytes={offset}-{offset + chunk - 1}'
                try:
                    response = s3.get_object(Bucket=S3_BUCKET, Key=filename, Range=byte_range)
                    data = response['Body'].read()
                    offset += len(data)
                    yield data
                except ClientError as e:
                    logger.error(f"Error downloading file chunk: {str(e)}")
                    abort(500)

        headers = {
            'Content-Disposition': f'attachment; filename="{os.path.basename(filename)}"',
            'Content-Length': str(file_size),
        }
        return Response(generate(), headers=headers, direct_passthrough=True)
    except ClientError as e:
        logger.error(f"Error initiating file download: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/delete/<path:filename>', methods=['DELETE'])
def delete(filename):
    try:
        delete_file(filename)
        return jsonify({'message': 'File deleted successfully'}), 200
    except Exception as e:
        logger.error(f"Error deleting file: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/list')
def list_bucket_files():
    try:
        prefix = request.args.get('prefix', '')
        min_file_size = request.args.get('min_file_size', 0, type=int)
        files, folders = list_files_and_folders(prefix, min_file_size)
        file_data = []
        for file in files:
            mime_type, _ = mimetypes.guess_type(file['name'])
            preview_url = None
            if mime_type and (mime_type.startswith('image/') or mime_type == 'application/pdf' or mime_type.startswith('video/')):
                preview_url = get_file_url(file['name'])
            file_data.append({
                'name': file['name'],
                'size': file['size'],
                'preview_url': preview_url,
                'mime_type': mime_type,
                'type': 'file'
            })
        for folder in folders:
            file_data.append({
                'name': folder,
                'type': 'folder'
            })
        return jsonify({'files': file_data}), 200
    except Exception as e:
        logger.error(f"Error listing files and folders: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/create_folder', methods=['POST'])
def create_new_folder():
    folder_name = request.json.get('folder_name')
    if not folder_name:
        return jsonify({'error': 'Folder name is required'}), 400
    try:
        create_folder(folder_name)
        return jsonify({'message': 'Folder created successfully'}), 200
    except Exception as e:
        logger.error(f"Error creating folder: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.route('/delete_folder/<path:folder_name>', methods=['DELETE'])
def remove_folder(folder_name):
    try:
        delete_folder(folder_name)
        return jsonify({'message': 'Folder deleted successfully'}), 200
    except Exception as e:
        logger.error(f"Error deleting folder: {str(e)}")
        return jsonify({'error': str(e)}), 500

@app.errorhandler(500)
def internal_server_error(error):
    logger.error(f"Internal Server Error: {str(error)}")
    return jsonify({'error': 'Internal Server Error'}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)

document.addEventListener('DOMContentLoaded', () => {
    const dropZone = document.getElementById('drop-zone');
    const fileInput = document.getElementById('file-input');
    const fileList = document.getElementById('file-list');
    const messageDiv = document.getElementById('message');
    const loadingSpinner = document.getElementById('loading-spinner');
    const previewArea = document.getElementById('preview-area');
    const createFolderBtn = document.getElementById('create-folder-btn');
    const currentPathDiv = document.getElementById('current-path');
    const toggleFilesBtn = document.getElementById('toggle-files-btn');
    const toggleMenu = document.getElementById('toggle-menu');
    const showHiddenFilesCheckbox = document.getElementById('show-hidden-files');

    let currentPath = '';
    let showFiles = true;
    let hiddenFiles = new Set();
    let showHiddenFiles = false;

    ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
        dropZone.addEventListener(eventName, preventDefaults, false);
    });

    function preventDefaults(e) {
        e.preventDefault();
        e.stopPropagation();
    }

    ['dragenter', 'dragover'].forEach(eventName => {
        dropZone.addEventListener(eventName, highlight, false);
    });

    ['dragleave', 'drop'].forEach(eventName => {
        dropZone.addEventListener(eventName, unhighlight, false);
    });

    function highlight() {
        dropZone.classList.add('highlight');
    }

    function unhighlight() {
        dropZone.classList.remove('highlight');
    }

    dropZone.addEventListener('drop', handleDrop, false);

    function handleDrop(e) {
        const dt = e.dataTransfer;
        const files = dt.files;
        handleFiles(files);
    }

    fileInput.addEventListener('change', function() {
        handleFiles(this.files);
    });

    function handleFiles(files) {
        ([...files]).forEach(uploadFile);
    }

    async function uploadFile(file) {
        const chunkSize = 100 * 1024 * 1024;
        const filename = currentPath + file.name;

        const progressBarContainer = createProgressBar(file.name, 'upload');
        const cancelButton = createCancelButton(() => {
            progressBarContainer.remove();
            showMessage('Upload cancelled', 'info');
        });
        progressBarContainer.appendChild(cancelButton);

        if (file.size < chunkSize) {
            const formData = new FormData();
            formData.append('chunk', file);
            formData.append('filename', filename);
            formData.append('file_size', file.size);
            formData.append('chunk_number', 0);
            formData.append('total_chunks', 1);

            try {
                const response = await fetch('/upload_chunk', {
                    method: 'POST',
                    body: formData
                });

                if (!response.ok) {
                    const errorData = await response.json();
                    throw new Error(errorData.error || `HTTP error! status: ${response.status}`);
                }

                progressBarContainer.remove();
                showMessage('File uploaded successfully', 'success');
                listFiles(currentPath);
            } catch (error) {
                showMessage(`Error uploading file: ${error.message}`, 'error');
                console.error('Upload error:', error);
                progressBarContainer.remove();
            }
        } else {
            const chunks = Math.ceil(file.size / chunkSize);
            let uploadId;

            for (let chunk = 0; chunk < chunks; chunk++) {
                const formData = new FormData();
                formData.append('chunk', file.slice(chunk * chunkSize, (chunk + 1) * chunkSize));
                formData.append('filename', filename);
                formData.append('chunk_number', chunk);
                formData.append('total_chunks', chunks);
                formData.append('file_size', file.size);
                if (uploadId) {
                    formData.append('upload_id', uploadId);
                }

                try {
                    const response = await fetch('/upload_chunk', {
                        method: 'POST',
                        body: formData
                    });

                    if (!response.ok) {
                        const errorData = await response.json();
                        throw new Error(errorData.error || `HTTP error! status: ${response.status}`);
                    }

                    const result = await response.json();
                    if (result.upload_id) {
                        uploadId = result.upload_id;
                    }

                    const percentComplete = ((chunk + 1) / chunks) * 100;
                    updateProgressBar(progressBarContainer, percentComplete);

                } catch (error) {
                    showMessage(`Error uploading file: ${error.message}`, 'error');
                    console.error('Upload error:', error);
                    progressBarContainer.remove();
                    return;
                }
            }

            progressBarContainer.remove();
            showMessage('File uploaded successfully', 'success');
            listFiles(currentPath);
        }
    }

    function listFiles(prefix = '') {
        showLoading();
        const url = `/list?prefix=${encodeURIComponent(prefix)}`;
        fetch(url)
            .then(response => response.json())
            .then(data => {
                hideLoading();
                if (data.error) {
                    showMessage(data.error, 'error');
                } else {
                    updateFileList(data.files);
                    updateCurrentPath(prefix);
                }
            })
            .catch(error => {
                hideLoading();
                showMessage('Error fetching file list', 'error');
            });
    }

    function updateFileList(files) {
        fileList.innerHTML = '';
        if (currentPath) {
            const li = document.createElement('li');
            li.className = 'flex justify-between items-center py-2';
            li.innerHTML = `
                <button onclick="navigateUp()" class="bg-gray-300 hover:bg-gray-400 text-gray-800 font-bold py-1 px-2 rounded">
                    ../ (Up)
                </button>
            `;
            fileList.appendChild(li);
        }
        files.forEach(file => {
            if (file.type === 'folder' || (showFiles && (showHiddenFiles || !hiddenFiles.has(file.name)))) {
                const li = document.createElement('li');
                li.className = 'flex justify-between items-center py-2';
                if (file.type === 'folder') {
                    li.innerHTML = `
                        <span>${file.name}</span>
                        <div>
                            <button onclick="navigateToFolder('${file.name}')" class="bg-blue-500 hover:bg-blue-700 text-white font-bold py-1 px-2 rounded mr-2">
                                Open
                            </button>
                            <button onclick="deleteFolder('${file.name}')" class="bg-red-500 hover:bg-red-700 text-white font-bold py-1 px-2 rounded">
                                Delete
                            </button>
                        </div>
                    `;
                } else {
                    const isHidden = hiddenFiles.has(file.name);
                    li.innerHTML = `
                        <span>${file.name} (${formatFileSize(file.size)})</span>
                        <div>
                            ${file.preview_url ? `<button onclick="previewFile('${file.name}', '${file.preview_url}', '${file.mime_type}')" class="bg-green-500 hover:bg-green-700 text-white font-bold py-1 px-2 rounded mr-2">
                                Preview
                            </button>` : ''}
                            <button onclick="downloadFile('${file.name}')" class="bg-blue-500 hover:bg-blue-700 text-white font-bold py-1 px-2 rounded mr-2">
                                Download
                            </button>
                            <button onclick="deleteFile('${file.name}')" class="bg-red-500 hover:bg-red-700 text-white font-bold py-1 px-2 rounded mr-2">
                                Delete
                            </button>
                            <button onclick="toggleFileVisibility('${file.name}')" class="bg-yellow-500 hover:bg-yellow-700 text-white font-bold py-1 px-2 rounded">
                                <i class="fas ${isHidden ? 'fa-eye-slash' : 'fa-eye'}"></i>
                            </button>
                        </div>
                    `;
                }
                fileList.appendChild(li);
            }
        });
    }

    function formatFileSize(bytes) {
        if (bytes === 0) return '0 Bytes';
        const k = 1024;
        const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
    }

    window.downloadFile = function(filename) {
        const progressBarContainer = createProgressBar(filename, 'download');
        const abortController = new AbortController();
        const cancelButton = createCancelButton(() => {
            abortController.abort();
            progressBarContainer.remove();
            showMessage('Download cancelled', 'info');
        });
        progressBarContainer.appendChild(cancelButton);

        fetch(`/download/${encodeURIComponent(currentPath + filename)}`, { signal: abortController.signal })
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                const reader = response.body.getReader();
                const contentLength = +response.headers.get('Content-Length');
                let receivedLength = 0;

                return new Response(
                    new ReadableStream({
                        start(controller) {
                            function push() {
                                reader.read().then(({ done, value }) => {
                                    if (done) {
                                        controller.close();
                                        progressBarContainer.remove();
                                        return;
                                    }
                                    receivedLength += value.length;
                                    const percentComplete = (receivedLength / contentLength) * 100;
                                    updateProgressBar(progressBarContainer, percentComplete);
                                    controller.enqueue(value);
                                    push();
                                });
                            }
                            push();
                        }
                    })
                );
            })
            .then(response => response.blob())
            .then(blob => {
                const url = window.URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.style.display = 'none';
                a.href = url;
                a.download = filename;
                document.body.appendChild(a);
                a.click();
                window.URL.revokeObjectURL(url);
            })
            .catch(error => {
                if (error.name === 'AbortError') {
                    showMessage('Download cancelled', 'info');
                } else {
                    showMessage('Error downloading file', 'error');
                    console.error('Download error:', error);
                }
                progressBarContainer.remove();
            });
    }

    window.deleteFile = function(filename) {
        if (confirm(`Are you sure you want to delete ${filename}?`)) {
            fetch(`/delete/${encodeURIComponent(currentPath + filename)}`, { method: 'DELETE' })
                .then(response => response.json())
                .then(data => {
                    if (data.error) {
                        showMessage(data.error, 'error');
                    } else {
                        showMessage('File deleted successfully', 'success');
                        listFiles(currentPath);
                    }
                })
                .catch(error => {
                    showMessage('Error deleting file', 'error');
                    console.error('Delete error:', error);
                });
        }
    }

    window.previewFile = function(filename, previewUrl, mimeType) {
        console.log('Previewing file:', filename, 'URL:', previewUrl, 'MIME:', mimeType);
        previewArea.innerHTML = '';
        if (mimeType.startsWith('image/')) {
            previewArea.innerHTML = `<img src="${previewUrl}" alt="${filename}" class="max-w-full h-auto">`;
        } else if (mimeType === 'application/pdf') {
            previewArea.innerHTML = `<iframe src="${previewUrl}" width="100%" height="600px"></iframe>`;
        } else if (mimeType.startsWith('video/')) {
            previewArea.innerHTML = `
                <video width="100%" height="auto" controls>
                    <source src="${previewUrl}" type="${mimeType}">
                    Your browser does not support the video tag.
                </video>`;
        } else {
            previewArea.innerHTML = '<p>Preview not available for this file type.</p>';
        }
    }

    function showMessage(message, type) {
        messageDiv.textContent = message;
        messageDiv.className = type === 'error' ? 'text-red-500' : type === 'info' ? 'text-blue-500' : 'text-green-500';
        setTimeout(() => {
            messageDiv.textContent = '';
            messageDiv.className = '';
        }, 5000);
    }

    function showLoading() {
        loadingSpinner.classList.remove('hidden');
    }

    function hideLoading() {
        loadingSpinner.classList.add('hidden');
    }

    function createProgressBar(filename, type) {
        const progressBarContainer = document.createElement('div');
        progressBarContainer.className = 'mt-4';
        progressBarContainer.innerHTML = `
            <p>${type === 'upload' ? 'Uploading' : 'Downloading'} ${filename}</p>
            <div class="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700">
                <div class="bg-blue-600 h-2.5 rounded-full" style="width: 0%"></div>
            </div>
        `;
        document.getElementById('progress-bars').appendChild(progressBarContainer);
        return progressBarContainer;
    }

    function updateProgressBar(progressBarContainer, percentComplete) {
        const progressBar = progressBarContainer.querySelector('.bg-blue-600');
        progressBar.style.width = `${percentComplete}%`;
    }

    function createCancelButton(cancelCallback) {
        const cancelButton = document.createElement('button');
        cancelButton.textContent = 'Cancel';
        cancelButton.className = 'bg-red-500 hover:bg-red-700 text-white font-bold py-1 px-2 rounded mt-2';
        cancelButton.onclick = cancelCallback;
        return cancelButton;
    }

    createFolderBtn.addEventListener('click', () => {
        const folderName = prompt('Enter folder name:');
        if (folderName) {
            createFolder(folderName);
        }
    });

    function createFolder(folderName) {
        const fullPath = currentPath + folderName;
        fetch('/create_folder', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ folder_name: fullPath }),
        })
        .then(response => response.json())
        .then(data => {
            if (data.error) {
                showMessage(data.error, 'error');
            } else {
                showMessage('Folder created successfully', 'success');
                listFiles(currentPath);
            }
        })
        .catch(error => {
            showMessage('Error creating folder', 'error');
            console.error('Create folder error:', error);
        });
    }

    window.deleteFolder = function(folderName) {
        if (confirm(`Are you sure you want to delete the folder ${folderName} and all its contents?`)) {
            const fullPath = currentPath + folderName;
            fetch(`/delete_folder/${encodeURIComponent(fullPath)}`, { method: 'DELETE' })
                .then(response => response.json())
                .then(data => {
                    if (data.error) {
                        showMessage(data.error, 'error');
                    } else {
                        showMessage('Folder deleted successfully', 'success');
                        listFiles(currentPath);
                    }
                })
                .catch(error => {
                    showMessage('Error deleting folder', 'error');
                    console.error('Delete folder error:', error);
                });
        }
    }

    window.navigateToFolder = function(folderName) {
        currentPath += folderName;
        listFiles(currentPath);
    }

    window.navigateUp = function() {
        const parts = currentPath.split('/');
        parts.pop();
        parts.pop();
        currentPath = parts.join('/') + '/';
        listFiles(currentPath);
    }

    function updateCurrentPath(path) {
        currentPathDiv.textContent = `Current Path: ${path || 'Root'}`;
        currentPath = path;
    }

    toggleFilesBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        toggleMenu.classList.toggle('show');
    });

    document.addEventListener('click', (e) => {
        if (!toggleFilesBtn.contains(e.target) && !toggleMenu.contains(e.target)) {
            toggleMenu.classList.remove('show');
        }
    });

    showHiddenFilesCheckbox.addEventListener('change', () => {
        showHiddenFiles = showHiddenFilesCheckbox.checked;
        listFiles(currentPath);
    });

    window.toggleFileVisibility = function(filename) {
        if (hiddenFiles.has(filename)) {
            hiddenFiles.delete(filename);
        } else {
            hiddenFiles.add(filename);
        }
        listFiles(currentPath);
    }

    listFiles();
});
